import Foundation
import XCTest

func XCTAssertEqual<T:Equatable>(actual: T?, expected: T?, _ message: String = "", file: String = #file, line: UInt = #line) {
  switch (actual, expected) {
  case (nil, nil): break
  case (nil, _): XCTFail("(\"nil\") is not equal to (\"\(expected)\")", file: #file, line: line)
